# Step 8a: Logic Coder (Blockly) + PLC runtime, standalone
import json
from playwright.sync_api import sync_playwright
import os; S=os.environ.get('HYDRA_ROOT', os.path.abspath(os.path.join(os.path.dirname(os.path.abspath(__file__)), '..' if os.path.basename(os.path.dirname(os.path.abspath(__file__)))=='tests' else '../..')))
R=[]
def check(n,c,x=''): R.append(('PASS' if c else 'FAIL',n,str(x)[:300]))
with sync_playwright() as p:
    b=p.chromium.launch(); ctx=b.new_context(viewport={'width':1600,'height':960}, accept_downloads=True); pg=ctx.new_page()
    errs=[]; pg.on('pageerror',lambda e: errs.append(str(e))); pg.on('console',lambda m: errs.append('console:'+m.text) if m.type=='error' else None)
    pg.goto('file://'+S+'/dist/HYDRA/HYDRA.html'); pg.wait_for_timeout(2500); ev=pg.evaluate
    pg.add_script_tag(path=S+'/tests/t8/seqprog.js')
    H="window.HYDRA"; P="window.HYDRA.plc"; L="window.HYDRA.plc.state"
    check('version 0.8.0', ev(f"{H}.version")=='0.8.0')
    check('Blockly not loaded at start (lazy)', ev("!window.HYDRA_BLOCKLY"))
    # ---------- launcher + chooser + new program ----------
    ev(f"{H}.Pj.createProject({{name:'S8a', template:'blank', unitSystem:'SI-bar'}})"); pg.wait_for_timeout(400)
    check('launcher says ready', 'ready' in ev("[...document.querySelectorAll('.launch')].find(x=>x.textContent.includes('Logic Coder'))?.textContent||''"))
    ev(f"{H}.cmds.runCmd('launch.logic')"); pg.wait_for_timeout(500)
    check('Logic Coder opens with chooser', 'Logic Coder' in pg.inner_text('.hd') and 'New program' in pg.inner_text('.hd'))
    pg.click('.hd button:has-text("New program")'); pg.wait_for_timeout(2500)
    check('block editor loads (Blockly injected)', ev("!!window.HYDRA_BLOCKLY && !!document.querySelector('.lc-ws .blocklySvg')"))
    pid=ev(f"{H}.S.tabs.value.find(t=>t.id===window.HYDRA.S.activeTab.value).nodeId")
    pr=ev(f"{H}.S.project.value.programs['{pid}']")
    check('new program: Blocks, five entry points, scan 10 ms', pr['language']=='Blocks' and sorted(b['type'] for b in pr['ws']['blocks']['blocks'])==sorted(['hy_start','hy_main','hy_estop','hy_reset','hy_fault']) and pr['scanMs']==10, pr.get('language'))
    tb=pg.inner_text('.hd.lc .blocklyToolboxDiv'); check('toolbox categories', all(x in tb for x in ['Program','Logic','Loops & Waits','Sequence Steps','Timers & Counters','Math','Variables','I/O','Text & Alarms','My Blocks']), tb)
    check('entry points listed in left panel', all(x in pg.inner_text('.hd.lc .dleft') for x in ['ON START','MAIN LOOP','ON E-STOP','ON RESET','ON FAULT']))
    # every block type in the toolbox instantiates and renders
    bad=ev(f"""(()=>{{const B=window.HYDRA_BLOCKLY; const ws=B.getMainWorkspace(); const out=[]; const walk=c=>{{(c.contents||[]).forEach(x=>{{ if(x.kind==='block'){{ try{{ const b=B.serialization.blocks.append(x, ws); b.dispose(false); }}catch(e){{ out.push(x.type+': '+e.message) }} }} if(x.contents) walk(x); }});}}; walk({P}.blocks.toolbox()); return out; }})()""")
    check('all toolbox blocks create without error', not bad, bad)
    # ---------- the Sequence sample: signals from its sheets ----------
    ev(f"{H}.actions.openSampleCopy('s_sequence')"); pg.wait_for_timeout(1200)
    T=ev(f"(()=>{{const t={P}.signals.signals({H}.S.project.value); return {{sigs:t.sigs.map(s=>[s.id.split(':')[0],s.tag,s.addr,s.dir]), cyls:t.cyls.map(c=>c.tag)}} }})()")
    di=[s for s in T['sigs'] if s[3]=='in']; do=[s for s in T['sigs'] if s[3]=='out']
    check('I/O table: 5 PLC inputs I0.0–I0.4', [s[2] for s in di]==['I0.0','I0.1','I0.2','I0.3','I0.4'] and all(s[0]=='plc' for s in di), di)
    check('I/O table: 4 PLC outputs Q0.0–Q0.3 (solenoids through the PLC, not doubled)', [s[2] for s in do if s[0]=='plc']==['Q0.0','Q0.1','Q0.2','Q0.3'] and not any(s[0]=='sol' for s in do), do)
    check('pump drive offered as a direct output; cylinders 1A1 2A1 with position / speed', any(s[0]=='drv' for s in do) and T['cyls']==['1A1','2A1'] and sum(1 for s in T['sigs'] if s[3]=='ain')==4, T)
    pid=ev(f"{H}.S.addNode('program', null, undefined, 'Auto_Cycle')")
    ev(f"(()=>{{const T={P}.signals.signals({H}.S.project.value); {L}.writeProg('{pid}', x=>{{ x.ws=mkSeqProg(T); x.sheet='none'; }}); }})()")
    ev(f"{H}.S.openSheetTab('{pid}')"); pg.wait_for_timeout(2200)
    c=ev(f"(()=>{{const c={L}.compileProg({H}.S.project.value,'{pid}'); return [c.ok, c.issues.map(i=>i.level+': '+i.text), c.seqs.map(s=>s.steps.map(x=>x.id+'>'+x.next).join(' '))]}})()")
    check('sequence program compiles: S0>S1 … S4>S0', c[0] and c[2]==['S0>S1 S1>S2 S2>S3 S3>S4 S4>S0'], c)
    txt=ev("[...document.querySelectorAll('.lc-ws .blocklyText')].map(x=>x.textContent.replace(/\u00a0/g,' ')).join('|')")
    check('dropdowns show tag · address', '1Y1 · Q0.0' in txt and '1S1 · I0.0' in txt, txt[:200])
    io=pg.inner_text('.lcdock'); check('I/O table in the dock with addresses', 'I0.0' in io and 'Q0.3' in io and 'B_Start' in io)
    # ---------- run, standalone inputs ----------
    pg.click('.lcrun'); pg.wait_for_timeout(300)
    st=ev(f"{L}.RT.value.rt.state"); check('Run starts the program', st=='running', st)
    check('ON START ran (message shown)', 'Running' in pg.inner_text('.hd.lc .lcmsg'))
    sig=lambda tag: ev(f"{P}.signals.signals({H}.S.project.value).sigs.find(s=>s.tag==='{tag}').id")
    cyl=lambda tag: ev(f"{P}.signals.signals({H}.S.project.value).cyls.find(s=>s.tag==='{tag}').id")
    setsim=lambda k,v: ev(f"(()=>{{const r={L}.RT.value.rt; r.sim['{k}']={json.dumps(v)}; window.HYDRA.plc.state.simStore.get('{pid}')}})()")
    cur=lambda: ev(f"{L}.RT.value.rt.seqs.AUTO && {L}.RT.value.rt.seqs.AUTO.cur")
    out=lambda tag: ev(f"!!{L}.RT.value.rt.out['{sig(tag)}']")
    A,Bc=cyl('1A1'),cyl('2A1')
    setsim(A+'-',True); setsim(Bc+'-',True); pg.wait_for_timeout(150)
    check('waits in S0 for start', cur()=='S0' and not out('1Y1'), cur())
    # click the 1S1 input in the I/O table
    pg.click(f'.lcio tr:has(td:has-text("1S1")) .lcbool'); pg.wait_for_timeout(200)
    check('clicking an input in the I/O table switches it', ev(f"{L}.RT.value.rt.sim['{sig('1S1')}']")==True)
    check('S1: A+ → 1Y1 ON (GRAFCET action while step active)', cur()=='S1' and out('1Y1') and not out('2Y1'), (cur(), out('1Y1')))
    setsim(A+'-',False); setsim(A+'+',True); pg.wait_for_timeout(150)
    check('S2: B+ → 2Y1 ON, 1Y1 OFF', cur()=='S2' and out('2Y1') and not out('1Y1'), cur())
    setsim(Bc+'-',False); setsim(Bc+'+',True); pg.wait_for_timeout(200)
    check('TRUE FOR 0.5 s holds S2 until the dwell is over', cur()=='S2', cur())
    pg.wait_for_timeout(600)
    check('… then S3: A− (1Y2)', cur()=='S3' and out('1Y2'), cur())
    setsim(A+'+',False); setsim(A+'-',True); pg.wait_for_timeout(200)
    check('S4: B− (2Y2)', cur()=='S4' and out('2Y2'), cur())
    setsim(sig('1S1'),False); setsim(Bc+'+',False); setsim(Bc+'-',True); pg.wait_for_timeout(200)
    check('back to S0, counter counted one cycle', cur()=='S0' and ev(f"{L}.RT.value.rt.counters.Cycles.CV")==1, ev(f"{L}.RT.value.rt.counters.Cycles"))
    evs=ev(f"{L}.RT.value.rt.events.length"); check('event log has every output change', evs>=8, evs)
    pg.click('.lcdock button:has-text("Watch")'); pg.wait_for_timeout(200)
    w=pg.inner_text('.lcdock'); check('watch shows the sequence, its step and the counter', 'AUTO' in w and 'S0' in w and 'Cycles' in w, w[:300])
    r=ev("(()=>{const ws=window.HYDRA_BLOCKLY.getMainWorkspace(); const b=ws.getAllBlocks(false).find(b=>b.type==='hy_act'); ws.centerOnBlock(b.id); const r=b.getSvgRoot().getBoundingClientRect(); return [r.x+12,r.y+10]})()"); pg.mouse.click(r[0],r[1]); pg.wait_for_timeout(300)
    ri=pg.inner_text('.hd.lc .dright'); check('click a block → inspector: linked part, address, live value', 'ACTIVATE' in ri and 'Q0.' in ri and 'solenoid' in ri, ri[:200])
    # live highlighting
    cls=ev("document.querySelectorAll('.lc-ws .hy-step, .lc-ws .hy-exec').length"); check('live highlighting on executed blocks / active step', cls>=2, cls)
    # ---------- pause / scan / stop ----------
    pg.click('.hd.lc button:has-text("Pause")'); pg.wait_for_timeout(100)
    n0=ev(f"{L}.RT.value.rt.scanNo"); pg.click('.hd.lc button:has-text("Scan")'); pg.wait_for_timeout(100); n1=ev(f"{L}.RT.value.rt.scanNo")
    check('Pause, then Scan executes exactly one scan', ev(f"{L}.RT.value.rt.state")=='paused' and n1==n0+1, (n0,n1))
    pg.click('.hd.lc button:has-text("Resume")'); pg.wait_for_timeout(100)
    # ---------- breakpoint ----------
    s2=ev(f"{L}.RT.value.rt.c.seqs[0].steps[2].block")
    ev(f"{L}.bps('{pid}').add('{s2}'); {L}.tick.value++")
    setsim(sig('1S1'),True); setsim(A+'-',True); setsim(A+'+',False); pg.wait_for_timeout(150); setsim(A+'-',False); setsim(A+'+',True); pg.wait_for_timeout(300)
    r=ev(f"(()=>{{const r={L}.RT.value.rt; return [r.state, r.bpAt, r.seqs.AUTO.cur]}})()")
    check('breakpoint pauses before the marked step', r[0]=='paused' and r[1]==s2 and r[2]=='S2', r)
    check('breakpoint block marked on the canvas', ev("document.querySelectorAll('.lc-ws .hy-at').length")>=1)
    ev(f"{L}.bps('{pid}').clear()"); pg.click('.hd.lc button:has-text("Resume")'); pg.wait_for_timeout(150)
    check('resume continues past the breakpoint', ev(f"{L}.RT.value.rt.state")=='running')
    # ---------- force ----------
    pg.click('.lcdock button:has-text("I/O table")'); pg.wait_for_timeout(150)
    pg.select_option('.lcio tr:has(td:has-text("2Y2")) select', 'ON'); pg.wait_for_timeout(150)
    check('force an output ON (row marked)', out('2Y2') and ev("!!document.querySelector('.lcio tr.forced')"))
    pg.select_option('.lcio tr:has(td:has-text("2Y2")) select', ''); pg.wait_for_timeout(150)
    check('release the force', not out('2Y2'))
    # ---------- E-stop ----------
    pg.click('.hd.lc .lcestop'); pg.wait_for_timeout(200)
    r=ev(f"(()=>{{const r={L}.RT.value.rt; return [r.state, Object.values(r.out).some(Boolean)]}})()")
    check('E-STOP: ON E-STOP runs, all outputs off, MAIN LOOP halted', r[0]=='estop' and not r[1], r)
    check('E-stop banner and alarm', 'E-STOP' in pg.inner_text('.hd.lc .lcbar') and ev(f"{L}.RT.value.rt.alarms.some(a=>a.code==='F-001'&&a.active)"))
    pg.click('.hd.lc button:has-text("Reset")'); pg.wait_for_timeout(150)
    check('Reset refused while the E-stop is still pressed', ev(f"{L}.RT.value.rt.state")=='estop')
    pg.click('.hd.lc .lcestop'); pg.wait_for_timeout(100); pg.click('.hd.lc button:has-text("Reset")'); pg.wait_for_timeout(200)
    check('released + Reset → ON RESET (sequence back to S0) and running', ev(f"{L}.RT.value.rt.state")=='running' and cur()=='S0', cur())
    # ---------- trend + alarms tab + exports ----------
    pg.click('.lcio tr:has(td:has-text("1Y1")) .lctr'); pg.wait_for_timeout(500)
    pg.click('.lcdock button:has-text("Trend")'); pg.wait_for_timeout(300)
    check('trend records the chosen signal', ev("document.querySelectorAll('.lctrend path').length")==1)
    with pg.expect_download() as d: pg.click('.lcdock button:has-text("CSV")')
    csvt=open(d.value.path()).read(); check('timing trace CSV', csvt.startswith('t (s),1Y1'), csvt[:60])
    pg.click('.lcdock button:has-text("Alarms")'); pg.wait_for_timeout(150)
    check('alarm list shows the E-stop with its time', 'Emergency stop' in pg.inner_text('.lcdock'))
    pg.click('.hd.lc button:has-text("Stop")'); pg.wait_for_timeout(150)
    check('Stop: stopped, outputs off', ev(f"{L}.RT.value.rt.state")=='stopped' and not any(ev(f"Object.values({L}.RT.value.rt.out)")))
    # ---------- tags are friendly names over permanent IDs ----------
    el=ev(f"Object.values({H}.S.project.value.circuits).find(c=>c.type==='electric').id")
    q0=ev(f"{H}.S.project.value.circuits['{el}'].components.find(c=>c.tag==='Q0.0').id")
    ev(f"{H}.designer.st.setComp('{el}','{q0}','t',x=>{{x.tag='Q1.7'}})"); pg.wait_for_timeout(500)
    txt=ev("[...document.querySelectorAll('.lc-ws .blocklyText')].map(x=>x.textContent.replace(/\u00a0/g,' ')).join('|')")
    c=ev(f"{L}.compileProg({H}.S.project.value,'{pid}').ok")
    check('re-address Q0.0 → Q1.7: block follows (hidden ID), program still valid', '1Y1 · Q1.7' in txt and c, txt[:160])
    # delete the PLC output → missing component error, Run blocked
    ev(f"{H}.designer.st.deleteIds('{el}',['{q0}'])"); pg.wait_for_timeout(500)
    c=ev(f"(()=>{{const c={L}.compileProg({H}.S.project.value,'{pid}'); return [c.ok, c.issues.filter(i=>i.level==='err').map(i=>i.text)]}})()")
    check('deleted part → error “missing component”, Run blocked', not c[0] and any('missing component' in x for x in c[1]), c)
    check('missing block shows ⚠ on the canvas and a warning icon', '⚠ missing component' in ev("[...document.querySelectorAll('.lc-ws .blocklyText')].map(x=>x.textContent.replace(/\u00a0/g,' ')).join('|')"))
    pg.click('.lcrun'); pg.wait_for_timeout(300)
    check('Run refused with errors → rule check opens', ev(f"{L}.RT.value.rt.state")=='stopped' and 'missing component' in pg.inner_text('.lcdock'))
    ev(f"{H}.S.undo()"); pg.wait_for_timeout(400)
    check('undo the deletion → program valid again', ev(f"{L}.compileProg({H}.S.project.value,'{pid}').ok"))
    # ---------- block editor undo through Edit › Undo ----------
    nb=ev("window.HYDRA_BLOCKLY.getMainWorkspace().getAllBlocks(false).length")
    ev("(()=>{const ws=window.HYDRA_BLOCKLY.getMainWorkspace(); ws.getTopBlocks(true).find(b=>b.type==='hy_reset').dispose(true);})()"); pg.wait_for_timeout(500)
    nb2=ev("window.HYDRA_BLOCKLY.getMainWorkspace().getAllBlocks(false).length")
    saved=ev(f"{H}.S.project.value.programs['{pid}'].ws.blocks.blocks.some(b=>b.type==='hy_reset')")
    ev(f"{H}.cmds.runCmd('edit.undo')"); pg.wait_for_timeout(500)
    nb3=ev("window.HYDRA_BLOCKLY.getMainWorkspace().getAllBlocks(false).length")
    check('block edits save into the project; Edit › Undo restores them', nb2<nb and not saved and nb3==nb and ev(f"{H}.S.project.value.programs['{pid}'].ws.blocks.blocks.some(b=>b.type==='hy_reset')"), (nb,nb2,nb3,saved))
    # ---------- variables ----------
    ev(f"{L}.writeProg('{pid}', x=>{{ x.vars=[{{id:'v1',name:'Ready',type:'BOOL',init:'FALSE'}}] }})"); pg.wait_for_timeout(300)
    ev("""(()=>{const B=window.HYDRA_BLOCKLY; const ws=B.getMainWorkspace(); const st=ws.getTopBlocks(true).find(b=>b.type==='hy_start'); const v=B.serialization.blocks.append({type:'hy_var_set',fields:{VAR:'v1'},inputs:{V:{block:{type:'logic_boolean',fields:{BOOL:'TRUE'}}}}}, ws); st.nextConnection.targetBlock().nextConnection.connect(v.previousConnection); })()"""); pg.wait_for_timeout(600)
    ev(f"{L}.writeProg('{pid}', x=>{{ x.vars[0].name='MachineReady' }})"); pg.wait_for_timeout(400)
    txt=ev("[...document.querySelectorAll('.lc-ws .blocklyText')].map(x=>x.textContent.replace(/\u00a0/g,' ')).join('|')")
    check('typed variable: renaming keeps the blocks (shown with new name)', 'MachineReady' in txt, txt[:200])
    pg.click('.lcrun'); pg.wait_for_timeout(200)
    check('SET variable in ON START runs', ev(f"{L}.RT.value.rt.v.v1")==True)
    pg.click('.hd.lc button:has-text("Stop")')
    # ---------- fault ----------
    pid2=ev(f"{H}.S.addNode('program', null, undefined, 'Faulty')")
    fws={'blocks':{'blocks':[{'type':'hy_main','id':'m','x':10,'y':10,'next':{'block':{'type':'hy_var_set','id':'s','fields':{'VAR':'a'},'inputs':{'V':{'block':{'type':'math_arithmetic','id':'d','fields':{'OP':'DIVIDE'},'inputs':{'A':{'block':{'type':'math_number','id':'n1','fields':{'NUM':1}}},'B':{'block':{'type':'math_number','id':'n0','fields':{'NUM':0}}}}}}}}}},{'type':'hy_fault','id':'f','x':300,'y':10,'next':{'block':{'type':'hy_outs_off','id':'o'}}}]}}
    ev(f"{L}.writeProg('{pid2}', x=>{{ x.vars=[{{id:'a',name:'X',type:'FLOAT',init:'0'}}]; x.ws={json.dumps(fws)} }})")
    ev(f"{H}.S.openSheetTab('{pid2}')"); pg.wait_for_timeout(1800); pg.click('.lcrun'); pg.wait_for_timeout(300)
    check('runtime fault (division by zero): FAULT state, banner, block marked', ev(f"{L}.RT.value.rt.state")=='fault' and 'Division by zero' in pg.inner_text('.hd.lc .lcbar') and ev("document.querySelectorAll('.lc-ws .hy-at').length")>=1)
    pg.click('.hd.lc button:has-text("Stop")')
    # ---------- legacy ST program from the sample ----------
    leg=ev(f"Object.values({H}.S.project.value.nodes).find(n=>n.type==='program'&&n.name==='Sequence').id")
    ev(f"{H}.S.openSheetTab('{leg}')"); pg.wait_for_timeout(1800)
    lp=ev(f"{H}.S.project.value.programs['{leg}']")
    pg.click('.hd.lc .dright button:has-text("Program")'); pg.wait_for_timeout(150)
    check('older ST program: opens with blocks, the text is kept and shown', lp['language']=='Blocks' and bool(lp.get('code')) and 'STRUCTURED TEXT' in pg.inner_text('.hd.lc .dright').upper())
    # ---------- save / reopen ----------
    ev(f"{H}.S.openSheetTab('{pid}')"); pg.wait_for_timeout(1500)
    rt=ev(f"""(async()=>{{ const Pj={H}.Pj; const z=await Pj.toZip({H}.S.project.value); const r=await Pj.fromZip(z); const q=r.p.programs['{pid}']; return [q.language, q.ws.blocks.blocks.length, q.vars.length, JSON.stringify(q.ws)===JSON.stringify({H}.S.project.value.programs['{pid}'].ws)]; }})()""")
    check('.hydra save → open keeps the program (blocks, variables)', rt[0]=='Blocks' and rt[3] and rt[2]==1, rt)
    # program JSON export
    pg.click('.hd.lc button:has-text("Export")'); pg.wait_for_timeout(150)
    with pg.expect_download() as d: pg.click('.pop .menu [role=menuitem]:has-text("Program (JSON)"), .pop .menu button:has-text("Program (JSON)")')
    pj=json.load(open(d.value.path())); check('program JSON export', pj['format']=='hydra.program' and pj['workspace']['blocks']['blocks'], list(pj))
    # read-only project → editor read-only
    ev(f"{H}.S.setReadOnly(true)"); pg.wait_for_timeout(1500)
    check('read-only project: block editor is read-only', ev("window.HYDRA_BLOCKLY.getMainWorkspace().options.readOnly")==True)
    ev(f"{H}.S.setReadOnly(false)"); pg.wait_for_timeout(1200)
    # E-stop input from the electric sheet (NC)
    pg.click('.hd.lc .dright button:has-text("Program")'); pg.wait_for_timeout(150)
    check('program settings: scan, loop limit, stall, E-stop input', all(x.upper() in pg.inner_text('.hd.lc .dright').upper() for x in ['Scan time','Loop limit','Stall alarm','E-stop input']))
    # speed: 5× runs faster than real time
    ev(f"{L}.setSpeed(5)"); pg.click('.lcrun'); pg.wait_for_timeout(1000); tt=ev(f"{L}.RT.value.rt.t"); pg.click('.hd.lc button:has-text("Stop")'); ev(f"{L}.setSpeed(1)")
    check('speed 5×: about 5 s of machine time per second', 3.0<tt<6.5, tt)
    check('no page errors', not errs, errs[:5])
    pg.screenshot(path=S+'/tests/t8/s8a_end.png')
    b.close()
fails=[r for r in R if r[0]=='FAIL']
for r in R: print(r[0], r[1], '' if r[0]=='PASS' else r[2])
print(f'{len(R)-len(fails)}/{len(R)} passed')
